import re

METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
PERMS = {"ALLOW", "DENY"}
VAR = re.compile("\\{[A-Za-z0-9_-]+\\}")


def norm(p):
    return VAR.sub("{var}", p)


def segs(p):
    return [s for s in p.split("/") if s]


def is_proper_prefix(q, p):
    qs, ps = segs(q), segs(p)
    return len(qs) < len(ps) and ps[:len(qs)] == qs


def main():
    with open("/app/input.txt") as f:
        lines = [l.rstrip("\r") for l in f.read().split("\n")]

    i = 0
    ep_lines = []
    while i < len(lines) and lines[i].strip() != "":
        ep_lines.append(lines[i])
        i += 1
    while i < len(lines) and lines[i].strip() == "":
        i += 1
    block = []
    while i < len(lines) and lines[i].strip() != "":
        block.append(lines[i])
        i += 1
    rest = lines[i:]
    if block and block[0].split()[0].lower() in ("base", "exclude"):
        meta = block
        plan_lines = rest
    else:
        meta = []
        plan_lines = block + rest

    base = None
    excl = set()
    for line in meta:
        parts = line.split()
        if not parts:
            continue
        if parts[0].lower() == "base" and len(parts) >= 2 and base is None:
            base = parts[1]
        elif parts[0].lower() == "exclude":
            excl.update(parts[1:])

    endpoints = []
    for line in ep_lines:
        parts = line.split()
        if len(parts) != 4:
            break
        path, method, role, perm = parts
        m = method.upper()
        pm = perm.upper()
        if not path or m not in METHODS or pm not in PERMS or not role:
            break
        endpoints.append((path, m, role, pm))

    plan = []
    for line in plan_lines:
        if not line.strip():
            continue
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        m = method.upper()
        if not path or m not in METHODS:
            break
        plan.append((norm(path), m))

    def ok_path(p):
        return base is None or p.startswith(base)

    elig = [e for e in endpoints if ok_path(e[0])]

    canon = {}
    for path, m, role, pm in elig:
        canon.setdefault(norm(path), path)

    if not plan:
        keep_fn = lambda e: e[2] not in excl
    else:
        planset = set(plan)
        planned_norms = {norm(e[0]) for e in elig if (norm(e[0]), e[1]) in planset}
        all_norms = {norm(e[0]) for e in elig}
        parents = {q for q in all_norms if any(is_proper_prefix(q, p) for p in planned_norms)}
        parents_with_nonex = {norm(e[0]) for e in elig if e[2] not in excl and norm(e[0]) in parents}

        def keep_fn(e):
            n = norm(e[0])
            excluded = e[2] in excl
            if not excluded and (n, e[1]) in planset:
                return True
            if n in parents:
                if n in parents_with_nonex:
                    return not excluded
                return True
            return False

    seen = set()
    out = []
    for e in elig:
        if not keep_fn(e):
            continue
        n = norm(e[0])
        key = (n, e[1], e[2])
        if key in seen:
            continue
        seen.add(key)
        out.append((canon[n], e[1], e[2], e[3]))

    out.sort(key=lambda t: (-len(segs(t[0])), t[1], t[2], t[3]))

    if out:
        text = "".join(" ".join(t) + "\n" for t in out)
    else:
        text = "\n"
    with open("/app/output.txt", "w") as f:
        f.write(text)


if __name__ == "__main__":
    main()
